export function createHotelDirectoryUI(ctx){
 const {state,boot,esc,icon,btn,api,drawModal,footer,render,reload,choosingHotel}=ctx;let sequence=0;
 const tierName=tier=>tier==='deep'?'深度体验':tier==='connected'?'智能体验':'自动发现体验';
 function selector(includeSamples=true){const query=state.directoryQuery||{city:choosingHotel?'':boot.hotel.city,keyword:''},result=state.directoryResult;
  return `<div class="drawer-content"><div class="eyebrow">FIND YOUR STAY</div><h2>选择你的酒店</h2><form id="hotel-search-form" class="hotel-search-form"><label><span>城市</span><input name="city" aria-label="搜索酒店所在城市" value="${esc(query.city)}" maxlength="40" required></label><label><span>酒店名称</span><input name="keyword" aria-label="酒店名称" placeholder="输入酒店名称" value="${esc(query.keyword)}" maxlength="80" required></label><button class="primary" type="submit" ${state.directoryBusy?'disabled':''}>${icon('search')}${state.directoryBusy?'搜索中…':'搜索酒店'}</button></form>${state.directoryError?`<div class="error-box" role="alert">${esc(state.directoryError)}</div>`:''}
  ${!choosingHotel&&boot.hotel.tier!=='basic'?btn('search-experiences','查当前酒店体验：'+esc(boot.hotel.name),'text-btn'):''}${result?`<section class="directory-results"><div class="directory-section-label">${esc(result.city)} · ${result.items.length} 个结果</div>${result.items.length?result.items.map(h=>`<div class="directory-result">${h.image?`<img class="directory-thumb" src="${esc(h.image)}" alt="${esc(h.name)}平台图片" loading="lazy">`:''}<div><span class="tier-badge ${h.tier==='deep'?'deep':''}">${tierName(h.tier)}</span><h3>${esc(h.name)}</h3><p>${esc([h.brand,h.star,h.rating?'平台评分 '+h.rating:''].filter(Boolean).join(' · '))}</p><p>${esc(h.address||h.city)}</p>${h.identityConflict?'<p>平台信息发生变化，请先查看平台详情。</p>':''}</div>${h.identityConflict?(h.link?`<a class="text-btn" href="${esc(h.link)}" target="_blank" rel="noreferrer">平台详情 ↗</a>`:''):btn('switch-hotel',`查看 ${icon('arrow')}`,'directory-open',`data-id="${esc(h.openHotelId)}" aria-label="查看${esc(h.name)}"`)}</div>`).join(''):'<p class="directory-empty">没有找到匹配酒店。试试完整名称或换个城市。</p>'}</section>`:''}
  ${includeSamples?`<div class="directory-section-label">已核对的酒店样例</div><div class="hotel-options">${boot.hotels.map(h=>`<button class="hotel-option ${h.id===boot.hotel.id?'selected':''}" data-action="switch-hotel" data-id="${esc(h.id)}" aria-label="入住${esc(h.name)}"><span class="hotel-option-art ${h.id==='lohkah-xiamen'?'water':'city'}" aria-hidden="true">${icon(h.id==='lohkah-xiamen'?'leaf':'spark')}</span><span><strong>${esc(h.name)}</strong><small>${esc(h.city)} · ${esc(h.mood)} · 深度体验</small></span><span>${h.id===boot.hotel.id?icon('check'):icon('arrow')}</span></button>`).join('')}</div>`:''}</div>`;
 }
 async function search(form){const data=new FormData(form),mine=++sequence;state.directoryQuery={city:String(data.get('city')||'').trim(),keyword:String(data.get('keyword')||'').trim()};state.directoryBusy=true;state.directoryError=null;if(choosingHotel)render();else drawModal();
  try{const result=await api('/api/hotel-search',state.directoryQuery);if(mine===sequence)state.directoryResult=result;}catch(e){if(mine===sequence){state.directoryError=e.message;state.directoryResult=null;}}finally{if(mine===sequence){state.directoryBusy=false;if(choosingHotel)render();else if(state.modal?.type==='hotels')drawModal();}}
 }
 function home(){const h=boot.hotel;return `<div class="basic-heading"><span class="product-caption">YOUR STAY IS TAKING SHAPE.</span><button class="hotel-switch" data-action="hotels">${icon('pin')}${esc(h.city)}${icon('down')}</button></div><section class="basic-hero spatial-scene"><div class="basic-visual" aria-hidden="true">${h.image?`<img src="${esc(h.image)}" alt="">`:''}</div><span class="tier-badge">${esc([h.brand,h.star].filter(Boolean).join(' · ')||'酒店资料')}</span><h1>${esc(h.name)}</h1><p>${esc(h.address||h.city)}</p>${h.rating?`<p>平台评分 ${esc(h.rating)}${h.landmark?' · '+esc(h.landmark):''}</p>`:''}<div class="basic-actions">${h.platformLink?`<a class="primary" href="${esc(h.platformLink)}" target="_blank" rel="noreferrer">查看飞猪详情 ${icon('arrow')}</a>`:''}${btn('nearby',`探索周边 ${icon('compass')}`,'secondary')}</div></section><section class="enrichment-status" aria-live="polite">${state.enrichmentBusy?`<span class="spinner"></span><div><h2>正在发现这家酒店</h2><p class="enrichment-progress">${esc(state.enrichmentProgress||'正在连接飞猪…')}</p><small>首次查询需要一点时间，完成后即可浏览体验、生成安排。</small></div>`:`<div><h2>发现酒店里的体验</h2><p>${esc(state.enrichmentError||'查询餐饮、康体与特色空间，整理成你的入住体验。')}</p>${btn('enrich-hotel',state.enrichmentError?'重新查询体验':'发现酒店体验','primary small')}</div>`}</section>${h.description?`<section class="basic-description"><div class="directory-section-label">${h.descriptionSource?'已整理简介':'平台简介'}</div><p>${esc(h.description)}</p></section>`:''}<details class="basic-sources"><summary>资料来源</summary><p>酒店资料来自飞猪查询，${esc(h.queriedAt?new Date(h.queriedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'')}。平台酒店 ID：${esc(h.providerId)}。商品、价格和可用性以平台详情为准。</p>${h.descriptionSource?`<a href="${esc(h.descriptionSource)}" target="_blank" rel="noreferrer">简介来源 ↗</a><p>人工核对日期 ${esc(h.descriptionCheckedAt)}</p>`:''}<p>${h.image?'图片来自飞猪酒店查询，不代表具体体验所在位置。':'空间画面为产品视觉示意，非酒店实景。'}</p></details>${footer()}`;}
 async function load(refresh=false){
  if(state.enrichmentBusy)return;state.enrichmentBusy=true;state.enrichmentError=null;state.enrichmentProgress='正在连接飞猪…';render();
  try{
   const response=await fetch('/api/hotel-enrich',{method:'POST',headers:{'Content-Type':'application/json','X-Stay-Hotel':boot.hotel.id},body:JSON.stringify({refresh})});
   if(!response.ok){const error=await response.json();throw new Error(error.error||'酒店资料查询未完成');}
   const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',result;
   while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;
    while((end=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,end);buffer=buffer.slice(end+2);const type=block.match(/^event: (.+)$/m)?.[1],raw=block.match(/^data: (.+)$/m)?.[1];if(!raw)continue;const data=JSON.parse(raw);
     if(type==='progress'){state.enrichmentProgress=data.label;const target=document.querySelector('.enrichment-progress');if(target)target.textContent=data.label;}
     if(type==='error')throw new Error(data.error);if(type==='result')result=data;
    }
   }
   if(!result)throw new Error('连接已结束，但未收到酒店体验，请重试。');
   state.enrichmentBusy=false;await reload();
  }catch(error){state.enrichmentBusy=false;state.enrichmentError=error.message;render();}
 }
 function detail(p){return `${boot.hotel.image?`<figure class="hotel-overview-image"><img src="${esc(boot.hotel.image)}" alt="${esc(boot.hotel.name)}酒店整体图"><figcaption>酒店整体图片 · 非本项目实景</figcaption></figure>`:''}<div class="drawer-content connected-detail"><div class="eyebrow">${esc(p.english)}</div><h2>${esc(p.name)}</h2><p>${esc(p.intro)}</p><div class="connected-budget">${icon('clock')}${p.scheduleRequired?'场次与时长待确认':`建议留 ${p.duration||30} 分钟`}<span>${p.scheduleRequired?'先了解排期':'按你的节奏调整'}</span></div><dl class="fact-list"><div class="fact-row"><dt>参与</dt><dd>出发前确认开放、费用与入住权益</dd></div><div class="fact-row"><dt>位置</dt><dd>${esc(p.location)}</dd></div></dl><details class="guide-sources"><summary>为什么推荐这项体验？</summary><p>${p.contentVerification==='operator-attested'?'本条资料由操作人声明已核对，依据如下。':'飞猪 AI 搜索提供了以下内容，百炼据此整理。'}停留时长为产品建议，非酒店公布的服务时长。</p><blockquote>${esc(p.sourceEvidence||p.story)}</blockquote><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noreferrer">查看飞猪酒店详情 ↗</a><p class="note">查询日期 ${esc(p.sourceCheckedAt)} · ${p.contentVerification==='operator-attested'?'人工核对记录，不代表实时酒店状态。':'平台 AI 资料，未经酒店人工确认。'}开放时间、费用和路线未从介绍推测。</p></details><div class="drawer-actions">${btn('save',`${icon('heart')}${state.favorites.includes(p.id)?'已收藏':'加入喜欢'}`,'secondary',`data-id="${p.id}"`)}${btn(p.scheduleRequired?'participate':'plan-with',`${p.scheduleRequired?'先确认时间':'放进我的安排'} ${icon('arrow')}`,'primary',`data-id="${p.id}"`)}</div>${btn('participate','参与前，确认一下','secondary wide',`data-id="${p.id}"`)}</div>`;}
 function coverage(){const e=boot.hotel.enrichment;if(!e)return '';const coverage=e.coverage,missing=(coverage?.groups||[]).filter(g=>!g.represented);return `<details class="experience-coverage"><summary>已整理 ${e.count} 项体验 · 查看资料范围</summary><p>来自 ${esc(boot.hotel.experienceQueriedAt?.slice(0,10))} 的飞猪查询。仅覆盖本次取得的内容，不代表酒店全部项目。</p>${coverage?.limitReached?'<p>本次已达到首批整理上限，可能仍有其他项目。</p>':''}${missing.length?`<p>原文还出现${missing.map(g=>esc(g.label)).join('、')}线索，尚未全部形成酒店内体验；不会补写成已确认项目。</p>`:''}${e.related?.length?`<div class="coverage-related"><span>度假区周边线索</span>${e.related.map(p=>btn('related-nearby',esc(p.name),'chip',`data-keyword="${esc(p.name)}"`)).join('')}</div>`:''}<p>“度假区体验”需你主动选择后才加入安排；权益、到达方式及项目排期需另行确认。</p>${btn('refresh-experiences','重新获取体验资料','text-btn',state.enrichmentBusy?'disabled':'')}</details>`;}
 function status(){return boot.hotel.tier!=='connected'||!state.enrichmentBusy&&!state.enrichmentError?'':`<div class="enrichment-inline" role="status">${state.enrichmentBusy?`<span class="spinner"></span><span class="enrichment-progress">${esc(state.enrichmentProgress)}</span>`:`<span>${esc(state.enrichmentError)}</span>${btn('refresh-experiences','重试','text-btn')}`}</div>`;}
 function landing(){return `<section class="hotel-entry"><h1>你住哪家酒店？</h1><p>选对酒店，再发现值得体验的部分。</p>${selector(false)}</section>`;}
 return {selector,landing,search,home,load,detail,coverage,status};
}
